import React, { useCallback } from 'react';
import { chakra, useStyleConfig } from '@chakra-ui/react';
import { defineMessages, useIntl } from 'react-intl';
import { ZimmLink } from 'app/components/ui-kits/atoms/zimmLink';
import { useCartMessages } from 'app/hooks/useCartMessages';
import { usePendingWishlistItem } from './usePendingWishlistItem';
import type { WishlistMoveResult } from './usePendingWishlistItem';

export type { WishlistMoveResult };

const ZIMM_CART_ITEM_ACTIONS_RECIPE = 'ZimmCartItemActions';

const messages = defineMessages({
  remove: { id: 'zimm_cart_item_actions.remove', defaultMessage: 'Remove' },
  moveToWishlist: { id: 'zimm_cart_item_actions.move_to_wishlist', defaultMessage: 'Move to Wishlist' },
});

export type ZimmCartItemActionsProps = {
  /** SFCC product id — the stable identity used to match a resumed pending intent across an auth
   *  step, including across a basket merge. See `usePendingWishlistItem`'s own doc for why this
   *  is `productId`, not the line's `itemId`. */
  productId: string;
  /** Interpolated into the wishlist-success toast copy (`useCartMessages.notifyAddedToWishlist`)
   *  — never hardcoded at a call site. */
  productName: string;
  /**
   * Whether the current shopper is unauthenticated. Read once by the caller (e.g. from
   * `useCustomerType()`) and passed down as a plain prop, rather than this component calling
   * that hook itself — see this file's own architecture note below for why.
   */
  isGuest: boolean;
  /**
   * Removes this entire line (all units) from the cart — a single call, never looped, regardless
   * of the line's current quantity (SFCC-270 AC8 / SFCC-272 AC3). The actual SFCC
   * `removeItemFromBasket` call is the caller's own responsibility (SFCC-11 plan step 4.6,
   * `cartDrawerContainer.tsx`, not built yet) — this component only ever calls this prop once per
   * click, and again (at most once) if a wishlist move succeeds.
   */
  onRemove: () => void | Promise<void>;
  /**
   * Attempts the real wishlist-add for an authenticated shopper. The actual SDK call is the
   * caller's own responsibility (step 4.6) — this component only calls it and reacts to the
   * result. Resolves to a discriminated union so this component can choose the right feedback
   * without any data-fetching of its own — see `WishlistMoveResult`'s own doc.
   */
  onMoveToWishlist: () => Promise<WishlistMoveResult>;
  /**
   * Called when a guest clicks "Move to Wishlist" for this row, after the pending intent has
   * already been persisted (see `usePendingWishlistItem`). The caller is responsible for opening
   * the one shared wishlist auth drawer — see this file's own architecture note for why this
   * component does not open it directly.
   */
  onGuestWishlistClick: () => void;
};

/**
 * Molecule — the "Remove" / "Move to Wishlist" action links rendered below a cart line's quantity
 * stepper (SFCC-270 AC8, SFCC-272). Supplied by the caller into base `product-item`'s own
 * `secondaryActions` slot (already wired, `overrides/app/components/product-item/index.tsx:365`)
 * — this molecule does not inject itself into that structure, it is simply the node passed in.
 *
 * Architecture note — why this component does not call `useWishlistAuthDrawer` itself, despite
 * that hook being an auth-gating hook rather than a data-fetching one (so calling it from a
 * `ui-kits/` component is not, by itself, a `components.md` container/presentational violation —
 * `ZimmWishlistAuthDrawer`, `overrides/app/components/ui-kits/organisms/zimmWishlistAuthDrawer/
 * index.tsx:35-58`, is the existing precedent for exactly that). The SFCC-11 plan requires exactly
 * ONE `useWishlistAuthDrawer` instance for the whole cart (`intentId: 'cart-wishlist'`), and
 * explicitly rejects mounting one instance per line item — a multi-item bag would mount a
 * `useForm`, three `useAuthHelper`s, a `useAuthModal` and a drawer per row. Because this component
 * is itself rendered once per cart line (one per `secondaryActions` slot), calling that hook
 * directly here would reproduce exactly the rejected per-row shape. So the one real hook instance
 * must live above every row — the cart container, SFCC-11 plan step 4.6, not yet built — and this
 * component receives `isGuest` / `onGuestWishlistClick` as plain props instead, wired by that
 * container to its own single hoisted `handleTriggerClick`. `useCartMessages` below has no such
 * constraint: it is a stateless wrapper around Chakra's own `useToast()`
 * (`overrides/app/hooks/useCartMessages.ts`), safe to call from as many rendered instances as
 * there are cart lines — this divergence from a literal per-row hook call is deliberate and
 * disclosed in this step's own report, not silently resolved.
 *
 * @param props see ZimmCartItemActionsProps
 */
export const ZimmCartItemActions = ({
  productId,
  productName,
  isGuest,
  onRemove,
  onMoveToWishlist,
  onGuestWishlistClick,
}: ZimmCartItemActionsProps) => {
  const intl = useIntl();
  const styles = useStyleConfig(ZIMM_CART_ITEM_ACTIONS_RECIPE);
  const { notifyAddedToWishlist, notifyAlreadyInWishlist } = useCartMessages();

  // Shared by both the direct (already-authenticated) click path below and the post-auth resume
  // path (usePendingWishlistItem's onResume) — one implementation of "branch on the move result",
  // not two copies of the same logic.
  const attemptMoveToWishlist = useCallback(async () => {
    const result = await onMoveToWishlist();
    if (result.status === 'success') {
      await onRemove();
      notifyAddedToWishlist(productName);
    } else if (result.status === 'already-in-wishlist') {
      notifyAlreadyInWishlist();
    }
    // 'error': no AC or Figma copy exists for this branch — leave the item in the cart and emit
    // no message rather than invent feedback text (same "do not invent copy" principle the
    // SFCC-11 plan applies to its own unspecified error feedback elsewhere, e.g. step 5.1).
  }, [onMoveToWishlist, onRemove, notifyAddedToWishlist, notifyAlreadyInWishlist, productName]);

  const { beginPendingMove } = usePendingWishlistItem({
    productId,
    isGuest,
    onResume: attemptMoveToWishlist,
  });

  const handleWishlistClick = () => {
    if (isGuest) {
      beginPendingMove();
      onGuestWishlistClick();
      return;
    }
    void attemptMoveToWishlist();
  };

  return (
    <chakra.div __css={styles}>
      <ZimmLink size="small" label={intl.formatMessage(messages.remove)} onClick={() => void onRemove()} />
      <ZimmLink size="small" label={intl.formatMessage(messages.moveToWishlist)} onClick={handleWishlistClick} />
    </chakra.div>
  );
};

