1	import React from 'react';
2	import { describe, test, expect, vi, beforeEach } from 'vitest';
3	import { render, screen, fireEvent, waitFor } from '@testing-library/react';
4	import { ChakraProvider } from '@chakra-ui/react';
5	import { IntlProvider } from 'react-intl';
6	import theme from 'app/theme';
7	import { ZimmCartItemActions } from './index';
8	import type { WishlistMoveResult } from './index';
9	import { ZimmCartItemActions as ZimmCartItemActionsRecipe } from './zimmCartItemActions.css';
10	import { ZimmLink as ZimmLinkRecipe } from 'app/components/ui-kits/atoms/zimmLink/zimmLink.css';
11	
12	const { mockNotifyAddedToWishlist, mockNotifyAlreadyInWishlist } = vi.hoisted(() => ({
13	  mockNotifyAddedToWishlist: vi.fn(),
14	  mockNotifyAlreadyInWishlist: vi.fn(),
15	}));
16	
17	// Smallest-surface mock (testing.md's mocking guidance): this suite is ZimmCartItemActions's own
18	// contract, not useCartMessages's (already covered by useCartMessages.test.ts) — mocked here so
19	// no real Chakra toast/portal is involved in these assertions.
20	vi.mock('app/hooks/useCartMessages', () => ({
21	  useCartMessages: () => ({
22	    notifyAddedToWishlist: mockNotifyAddedToWishlist,
23	    notifyAlreadyInWishlist: mockNotifyAlreadyInWishlist,
24	    notifyMaxQuantityReached: vi.fn(),
25	  }),
26	}));
27	
28	// ZimmLink calls useSafeHref() unconditionally, which transitively reaches use-multi-site's
29	// MultiSiteContext — a JSX-in-.js base file Vitest's default transform cannot parse. Same known
30	// gap, same fix, as zimmLink/index.test.tsx's own identical mock: this suite never exercises an
31	// href (both links here are onClick-only, button-mode ZimmLinks), so the returned function is
32	// never actually invoked — it only needs to exist so the real module is never imported.
33	vi.mock('app/hooks/useSafeHref', () => ({
34	  useSafeHref: () => (href: string) => href,
35	}));
36	
37	const REMOVE_NAME = 'Remove';
38	const MOVE_TO_WISHLIST_NAME = 'Move to Wishlist';
39	const PRODUCT_ID = 'product-abc';
40	const PRODUCT_NAME = 'Cloud 91 Small Clutch';
41	
42	const success = (): Promise<WishlistMoveResult> => Promise.resolve({ status: 'success' });
43	const alreadyInWishlist = (): Promise<WishlistMoveResult> => Promise.resolve({ status: 'already-in-wishlist' });
44	
45	// Resolves each callback to whatever `props` actually supplies (falling back to a fresh vi.fn()
46	// default) BEFORE rendering, and returns those SAME resolved references — never the unused
47	// default a caller-supplied override would otherwise shadow in JSX. Spreading `props` after these
48	// defaults but asserting on the pre-spread locals was a real bug caught by this suite's own first
49	// run: overriding `onMoveToWishlist` in a test still resolved assertions against the default,
50	// untouched mock, silently passing for the wrong reason.
51	const renderActions = (props: Partial<React.ComponentProps<typeof ZimmCartItemActions>> = {}) => {
52	  const onRemove = props.onRemove ?? vi.fn();
53	  const onMoveToWishlist = props.onMoveToWishlist ?? vi.fn(success);
54	  const onGuestWishlistClick = props.onGuestWishlistClick ?? vi.fn();
55	  const utils = render(
56	    <IntlProvider locale="en">
57	      <ChakraProvider theme={theme}>
58	        <ZimmCartItemActions
59	          productId={PRODUCT_ID}
60	          productName={PRODUCT_NAME}
61	          isGuest={false}
62	          {...props}
63	          onRemove={onRemove}
64	          onMoveToWishlist={onMoveToWishlist}
65	          onGuestWishlistClick={onGuestWishlistClick}
66	        />
67	      </ChakraProvider>
68	    </IntlProvider>,
69	  );
70	  return { ...utils, onRemove, onMoveToWishlist, onGuestWishlistClick };
71	};
72	
73	describe('ZimmCartItemActions', () => {
74	  beforeEach(() => {
75	    vi.clearAllMocks();
76	  });
77	
78	  describe('default rendering (pass criterion 1)', () => {
79	    test('renders both links as buttons with the exact accessible names', () => {
80	      renderActions();
81	      expect(screen.getByRole('button', { name: REMOVE_NAME })).toBeInTheDocument();
82	      expect(screen.getByRole('button', { name: MOVE_TO_WISHLIST_NAME })).toBeInTheDocument();
83	    });
84	
85	    test('the row recipe declares no colour/hover/focus of its own — ZimmLink stays the single, uncontested styling surface for both links', () => {
86	      // See zimmCartItemActions.css.ts's own docblock: link.default and text.default resolve to
87	      // the same primitive (grey[900]), so a plain ZimmLink already renders the spec's colour —
88	      // adding a second, competing declaration here would fight ZimmLink's own recipe instead of
89	      // composing it (overrideStyling.md's "one canonical styling surface" rule).
90	      const baseStyle = ZimmCartItemActionsRecipe.baseStyle as Record<string, unknown>;
91	      expect(baseStyle.color).toBeUndefined();
92	      expect(baseStyle._hover).toBeUndefined();
93	      expect(baseStyle._focusVisible).toBeUndefined();
94	      expect(baseStyle.gap).toBe('var(--zimm-scale-xl)');
95	    });
96	  });
97	
98	  describe('focus-visible is inherited from ZimmLink and genuinely differs from default (pass criterion 2)', () => {
99	    // jsdom cannot exercise a real :focus-visible pseudo-class match (same disclosed limitation
100	    // zimmQuantityStepper/index.test.tsx's own "State 5" recipe-level assertions rely on) — this
101	    // proves the underlying premise directly from ZimmLink's own recipe object (the same one
102	    // useStyleConfig('ZimmLink', ...) resolves against for both links here) rather than
103	    // re-testing ZimmLink's own contract, which is zimmLink/index.test.tsx's job, not this file's.
104	    test('ZimmLink carries a real focus-visible outline with no equivalent default-state outline', () => {
105	      const large = ZimmLinkRecipe.baseStyle as Record<string, unknown>;
106	      expect(large.outline).toBeUndefined();
107	      expect((large._focusVisible as Record<string, unknown>).outline).toBe('var(--zimm-focus-ring)');
108	    });
109	  });
110	
111	  describe('no disabled state exists (pass criterion 3)', () => {
112	    test('neither link ever carries a disabled/aria-disabled attribute — there is no prop to request one', () => {
113	      renderActions();
114	      expect(screen.getByRole('button', { name: REMOVE_NAME })).not.toBeDisabled();
115	      expect(screen.getByRole('button', { name: REMOVE_NAME })).not.toHaveAttribute('aria-disabled');
116	      expect(screen.getByRole('button', { name: MOVE_TO_WISHLIST_NAME })).not.toBeDisabled();
117	      expect(screen.getByRole('button', { name: MOVE_TO_WISHLIST_NAME })).not.toHaveAttribute('aria-disabled');
118	    });
119	  });
120	
121	  describe('Remove (pass criteria 4 & 5 — one call regardless of the line quantity, which this component never receives or loops over)', () => {
122	    test('clicking Remove calls onRemove exactly once', () => {
123	      const { onRemove } = renderActions();
124	      fireEvent.click(screen.getByRole('button', { name: REMOVE_NAME }));
125	      expect(onRemove).toHaveBeenCalledTimes(1);
126	    });
127	
128	    test('clicking Remove twice still only issues two independent single calls — never a loop from one click', () => {
129	      const { onRemove } = renderActions();
130	      fireEvent.click(screen.getByRole('button', { name: REMOVE_NAME }));
131	      fireEvent.click(screen.getByRole('button', { name: REMOVE_NAME }));
132	      expect(onRemove).toHaveBeenCalledTimes(2);
133	    });
134	  });
135	
136	  describe('authenticated wishlist move — success (pass criterion 6)', () => {
137	    test('calls onMoveToWishlist, then onRemove, then emits the product-named success message', async () => {
138	      const { onMoveToWishlist, onRemove } = renderActions({ isGuest: false });
139	
140	      fireEvent.click(screen.getByRole('button', { name: MOVE_TO_WISHLIST_NAME }));
141	
142	      await waitFor(() => expect(onRemove).toHaveBeenCalledTimes(1));
143	      expect(onMoveToWishlist).toHaveBeenCalledTimes(1);
144	      expect(mockNotifyAddedToWishlist).toHaveBeenCalledWith(PRODUCT_NAME);
145	      expect(mockNotifyAlreadyInWishlist).not.toHaveBeenCalled();
146	    });
147	  });
148	
149	  describe('authenticated wishlist move — already in wishlist (pass criterion 7)', () => {
150	    test('emits the warning message and leaves the item in the cart — onRemove is never called', async () => {
151	      const { onRemove, onMoveToWishlist } = renderActions({
152	        isGuest: false,
153	        onMoveToWishlist: vi.fn(alreadyInWishlist),
154	      });
155	
156	      fireEvent.click(screen.getByRole('button', { name: MOVE_TO_WISHLIST_NAME }));
157	
158	      await waitFor(() => expect(onMoveToWishlist).toHaveBeenCalledTimes(1));
159	      expect(mockNotifyAlreadyInWishlist).toHaveBeenCalledTimes(1);
160	      expect(mockNotifyAddedToWishlist).not.toHaveBeenCalled();
161	      expect(onRemove).not.toHaveBeenCalled();
162	    });
163	  });
164	
165	  describe('guest click (pass criterion 8)', () => {
166	    test('opens the shared auth drawer via onGuestWishlistClick and leaves the item in the cart — the real move never runs', () => {
167	      const { onGuestWishlistClick, onMoveToWishlist, onRemove } = renderActions({ isGuest: true });
168	
169	      fireEvent.click(screen.getByRole('button', { name: MOVE_TO_WISHLIST_NAME }));
170	
171	      expect(onGuestWishlistClick).toHaveBeenCalledTimes(1);
172	      expect(onMoveToWishlist).not.toHaveBeenCalled();
173	      expect(onRemove).not.toHaveBeenCalled();
174	    });
175	  });
176	
177	  describe("pending-item resume across auth (pass criterion 9 — React-state half; the session-storage half and the 5-minute bound are usePendingWishlistItem.test.ts's own exhaustive cases, not re-derived here)", () => {
178	    test('a guest click, followed by the same instance re-rendering as authenticated, resumes the move automatically', async () => {
179	      const onMoveToWishlist = vi.fn(success);
180	      const onRemove = vi.fn();
181	      const onGuestWishlistClick = vi.fn();
182	      const { rerender } = render(
183	        <IntlProvider locale="en">
184	          <ChakraProvider theme={theme}>
185	            <ZimmCartItemActions
186	              productId={PRODUCT_ID}
187	              productName={PRODUCT_NAME}
188	              isGuest={true}
189	              onRemove={onRemove}
190	              onMoveToWishlist={onMoveToWishlist}
191	              onGuestWishlistClick={onGuestWishlistClick}
192	            />
193	          </ChakraProvider>
194	        </IntlProvider>,
195	      );
196	
197	      fireEvent.click(screen.getByRole('button', { name: MOVE_TO_WISHLIST_NAME }));
198	      expect(onMoveToWishlist).not.toHaveBeenCalled();
199	
200	      // Same mounted instance transitioning isGuest true -> false — the email-code / create-
201	      // account shape (the page never unloads), matching usePendingWishlistItem's own doc.
202	      rerender(
203	        <IntlProvider locale="en">
204	          <ChakraProvider theme={theme}>
205	            <ZimmCartItemActions
206	              productId={PRODUCT_ID}
207	              productName={PRODUCT_NAME}
208	              isGuest={false}
209	              onRemove={onRemove}
210	              onMoveToWishlist={onMoveToWishlist}
211	              onGuestWishlistClick={onGuestWishlistClick}
212	            />
213	          </ChakraProvider>
214	        </IntlProvider>,
215	      );
