import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { expect, userEvent, within } from 'storybook/test';
import { ZimmCartItemActions } from '.';
import type { WishlistMoveResult } from '.';

const meta: Meta<typeof ZimmCartItemActions> = {
  title: 'Commerce/ZimmCartItemActions',
  component: ZimmCartItemActions,
  parameters: { layout: 'padded' },
};

export default meta;

type Story = StoryObj<typeof ZimmCartItemActions>;

const PRODUCT_NAME = 'Cloud 91 Small Clutch';

const success = (): Promise<WishlistMoveResult> => Promise.resolve({ status: 'success' });
const alreadyInWishlist = (): Promise<WishlistMoveResult> => Promise.resolve({ status: 'already-in-wishlist' });

export const Default: Story = {
  args: {
    productId: 'product-abc',
    productName: PRODUCT_NAME,
    isGuest: false,
    onRemove: () => {},
    onMoveToWishlist: success,
    onGuestWishlistClick: () => {},
  },
};

/**
 * SFCC-272 AC5 / SFCC-11 plan step 4.4 pass criterion 6 — also closes step 4.3's own deferred
 * Storybook criterion (useCartMessages.ts had no rendered, clickable component to trigger one of
 * its three messages from at that step; this is the first one that does). Chakra's toast portals
 * outside canvasElement, so the assertion queries within(document.body) with this inline citation
 * — testing.md §Layer-2's only sanctioned use of that query, matching zimmDrawer/index.stories.tsx's
 * own precedent for a different portal (Drawer, not a toast).
 */
export const WishlistMoveSuccess: Story = {
  args: {
    productId: 'product-abc',
    productName: PRODUCT_NAME,
    isGuest: false,
    onRemove: () => {},
    onMoveToWishlist: success,
    onGuestWishlistClick: () => {},
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByRole('button', { name: 'Move to Wishlist' }));

    const doc = within(document.body);
    await expect(doc.findByText(`${PRODUCT_NAME} added to Wishlist`)).resolves.toBeInTheDocument();
  },
};

export const AlreadyInWishlist: Story = {
  args: {
    productId: 'product-abc',
    productName: PRODUCT_NAME,
    isGuest: false,
    onRemove: () => {},
    onMoveToWishlist: alreadyInWishlist,
    onGuestWishlistClick: () => {},
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByRole('button', { name: 'Move to Wishlist' }));

    const doc = within(document.body);
    await expect(doc.findByText('An item in your bag already exists in Wishlist')).resolves.toBeInTheDocument();
    // The item stays in the cart on this path (SFCC-272 AC6) — nothing in this story removes it,
    // there is simply no "item removed" state for a Storybook-isolated molecule to show.
  },
};

/** SFCC-272 AC7 — a guest click opens the shared auth drawer (the caller's own responsibility,
 *  see this component's own architecture note) and never attempts the real move. */
export const GuestClick: Story = {
  args: {
    productId: 'product-abc',
    productName: PRODUCT_NAME,
    isGuest: true,
    onRemove: () => {},
    onMoveToWishlist: success,
    onGuestWishlistClick: () => {},
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByRole('button', { name: 'Move to Wishlist' }));
    // No toast, no removal — this story's onGuestWishlistClick/onMoveToWishlist are unspied here
    // (see index.test.tsx for the call-count assertions); this play only proves the click doesn't
    // throw and nothing renders that shouldn't (no message node from this molecule itself).
    await expect(canvas.queryByText(`${PRODUCT_NAME} added to Wishlist`)).not.toBeInTheDocument();
  },
};

import { useEffect, useState } from 'react';
import {
  clearSessionJSONItem,
  getSessionJSONItem,
  setSessionJSONItem,
} from '@salesforce/retail-react-app/app/utils/utils';

/**
 * Outcome of one wishlist-move attempt. The actual SFCC SDK calls (wishlist add + cart removal)
 * are the caller's own responsibility — SFCC-11 plan step 4.6 (`cartDrawerContainer.tsx`, not
 * built yet) — this file only reports what happened, matching the exact discriminated-union
 * pattern `useCartMergeAndCap.ts`'s own `CartCapResult` already established
 * (`overrides/app/hooks/useCartMergeAndCap.ts:25-29`), per typescript.md's stated preference for
 * a discriminated union over a pile of optional fields.
 */
export type WishlistMoveResult =
  | { status: 'success' }
  | { status: 'already-in-wishlist' }
  | { status: 'error'; error: unknown };

/**
 * sessionStorage key for "a guest asked to move THIS specific cart line to their wishlist before
 * authenticating." Deliberately a distinct mechanism, and a distinct key, from
 * `useWishlistAuthDrawer.ts`'s own `PENDING_WISHLIST_INTENT_KEY`
 * (`overrides/app/hooks/useWishlistAuthDrawer.ts:43`): that key answers "which mounted drawer
 * instance's `onAuthSuccess` should fire after a social-IDP redirect" — its own
 * `PendingWishlistIntent` type carries only `intentId`/`timestamp`, no item identity at all.
 * This hook answers a different question — "which cart LINE was pending" — so it is a new,
 * separate mechanism rather than an addition to that shared type. The SFCC-11 plan explicitly
 * rejects adding an `itemId` field to that shared type: it has three other existing call sites
 * (header/rightBar, drawer-menu, product-view) and changing it is out of this step's scope.
 */
const PENDING_WISHLIST_CART_ITEM_KEY = 'zimmPendingWishlistCartItem';

/**
 * Same 5-minute bound as `useWishlistAuthDrawer.ts`'s own `PENDING_WISHLIST_INTENT_MAX_AGE_MS`
 * (`overrides/app/hooks/useWishlistAuthDrawer.ts:52` — `5 * 60 * 1000`), and the same reasoning:
 * long enough for a real auth round trip, short enough that a long-abandoned attempt cannot
 * misfire later against a much later, unrelated cart session. Not imported from that file — the
 * constant is not exported there, and this step does not modify that file (out of scope; see the
 * SFCC-11 plan step 4.4's manifest and its "explicitly rejected" list). Redefined here as an
 * independent, same-valued constant instead.
 */
const PENDING_WISHLIST_MAX_AGE_MS = 5 * 60 * 1000; // 5 minutes

type PendingWishlistCartItem = {
  /**
   * Matched against this row's own `productId`, not `itemId` — deliberate. A guest's basket may
   * be merged into a registered customer's basket between the guest's click and the shopper
   * completing auth (SFCC-250 step 4.1, `useWishlistAuthDrawer.ts`'s own `isRegistered` effect),
   * and that merge can change which `itemId` a given product line carries (it merges into a
   * destination basket via `createDestinationBasket: true`). `productId` is stable across that
   * boundary; `itemId` is not — keying the match on `itemId` would risk silently failing to
   * resume a legitimate pending move the moment a merge has actually happened. See this step's
   * own report for the related, still-open sequencing question this raises for step 4.6.
   */
  productId: string;
  timestamp: number;
};

export type UsePendingWishlistItemParams = {
  /** Identifies this cart line for matching a resumed intent — see PendingWishlistCartItem's own
   *  doc comment for why this is `productId`, not `itemId`. */
  productId: string;
  /** Whether the current shopper is unauthenticated. Passed down from the caller (e.g. read once
   *  from `useCustomerType()` at the cart container) rather than read by this hook itself — see
   *  `zimmCartItemActions/index.tsx`'s own architecture note for why. */
  isGuest: boolean;
  /** Called (no arguments) once a previously-pending move for THIS row should be attempted.
   *  Fires at most once per stored intent — never for another row's pending item, never twice
   *  for the same one. */
  onResume: () => void | Promise<void>;
};

export type UsePendingWishlistItemReturn = {
  /** Call when a guest clicks "Move to Wishlist" for this row — persists the pending intent to
   *  both React state (survives the email-code/create-account flows, which never unload the
   *  page) and session storage (survives the Apple/Google redirect, which reloads it), so
   *  `onResume` fires automatically once `isGuest` becomes false for this same product. */
  beginPendingMove: () => void;
};

/**
 * Hook — persists a guest's "move to wishlist" intent for one cart line across an authentication
 * step, and resumes it once the shopper is no longer a guest. Extracted per
 * `.claude/rules/components.md`'s extract-to-hook threshold: this is React state plus a
 * non-trivial effect (session-storage read/write/clear, a 5-minute age check, resuming after a
 * simulated page reload) that would otherwise sit inline in `ZimmCartItemActions`.
 *
 * Deliberately calls no auth or `commerce-sdk-react` hook itself — `isGuest` arrives as a plain
 * prop, and the actual move (`onResume`) is the caller's own already-composed function. Only ONE
 * `useWishlistAuthDrawer` instance may exist for the whole cart (SFCC-11 plan step 4.4's own
 * explicit rejection of "one per line item"), so that real hook cannot live inside a component
 * that mounts once per cart line — this hook stays calling-hook-free so it can safely mount once
 * per row, alongside it, without reproducing that rejected shape.
 *
 * @returns `beginPendingMove`, the one function a guest click calls.
 */
export const usePendingWishlistItem = ({
  productId,
  isGuest,
  onResume,
}: UsePendingWishlistItemParams): UsePendingWishlistItemReturn => {
  const [pending, setPending] = useState<PendingWishlistCartItem | undefined>(undefined);

  const beginPendingMove = () => {
    const intent: PendingWishlistCartItem = { productId, timestamp: Date.now() };
    setPending(intent);
    setSessionJSONItem(PENDING_WISHLIST_CART_ITEM_KEY, intent);
  };

  // Mirrors useWishlistAuthDrawer.ts's own redirect-consuming effect (that file's second
  // useEffect, [isRegistered]-only deps, overrides/app/hooks/useWishlistAuthDrawer.ts:252-259) —
  // runs on mount and on every `isGuest` change, not only on a true-to-false transition, because
  // a fresh mount after a real page reload (Apple/Google redirect) already has `isGuest === false`
  // on its very first render, with no transition to observe.
  useEffect(() => {
    if (isGuest) return;

    const stored = getSessionJSONItem(PENDING_WISHLIST_CART_ITEM_KEY) as PendingWishlistCartItem | undefined;
    // Only ever act on a stored intent that names THIS row's own product — a different row's
    // legitimate pending intent is left untouched (not cleared, not resumed) if it happens to
    // still be in storage when this effect runs.
    const mineFromStorage = stored?.productId === productId ? stored : undefined;
    const candidate = pending ?? mineFromStorage;
    if (!candidate) return;

    // Found something of mine — clear both stores now, regardless of whether it turns out to be
    // fresh or stale below (a stale intent must not linger either — nothing resumes it later).
    setPending(undefined);
    clearSessionJSONItem(PENDING_WISHLIST_CART_ITEM_KEY);

    const isFresh = Date.now() - candidate.timestamp <= PENDING_WISHLIST_MAX_AGE_MS;
    if (isFresh) {
      void onResume();
    }
  }, [isGuest]);

  return { beginPendingMove };
};

